"""전용 모델 결과 Notebook. 후반 재추론 없이 validation 재현만 수행."""
from pathlib import Path
import sys
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import os,time
import nbformat as nb
from nbclient import NotebookClient
from src.specialist_experiment import *


def main():
    for key,path in [('JUPYTER_PATH','outputs/jupyter'),('JUPYTER_RUNTIME_DIR','outputs/jupyter/runtime'),('IPYTHONDIR','outputs/ipython'),('MPLCONFIGDIR','outputs/.mplconfig')]:os.environ[key]=str(ROOT/path)
    book=nb.v4.new_notebook();book.metadata['kernelspec']={'name':'phm2018-v3','display_name':'PHM2018 V3 (로컬)','language':'python'}
    blocks=[
      ('markdown','# 16 장비 전용 모델 후속 연구: 03M02\n\n약20분의 파일럿 범위에서 최대3대까지 선정하기로 했으며, 사전 최소 조건을 모두 통과한03M02 한 대를 CUDA 학습했습니다. 전용 학습 효과와 장비별 임계값만 조정한 효과를 분리해 비교합니다.\n\n**후반20%는 이전 평가에서 이미 본 데이터이므로 독립 Holdout 시험이 아닙니다.** 기존 공통 모델과 최종 평가 파일을 보존했습니다. 이 Notebook은 저장된 후반 점수만 읽으며 전용 모델의 재현 확인에는 validation128행만 사용합니다.'),
      ('code',"from pathlib import Path\nimport sys,json,hashlib\nimport numpy as np,pandas as pd\nfrom IPython.display import display,Image\nROOT=Path.cwd()\nif ROOT.name=='notebooks':ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT))\nfrom src.specialist_experiment import OUT,PROTOCOL,readjson,digest,verify_previous,load\nfrom src.common import TABLES,CFG\nassert Path(sys.executable).resolve()==Path(CFG['python']).resolve()\ndef table(name):return pd.read_parquet(TABLES/('stage7_'+name+'.parquet'))\ndef figure(name):display(Image(filename=str(ROOT/('outputs/figures/stage7/'+name+'.png'))))\nverify_previous()\nselection=readjson(OUT/'selection.json')\nfrozen=readjson(OUT/'frozen_manifest.json')\naccess=readjson(OUT/'evaluation_access.json')\nassert access['status']=='complete' and not access['independent_final_test']\nassert access['specialist_prediction_passes_per_tool']==1\nprint('선정 장비:',selection['selected_tools'],'| 환경:',sys.executable)\ndisplay(PROTOCOL)"),
      ('markdown','## 1. 선정과 제외\n\n학습/검증 고장군집8/3개, 양성100/20행, 음성1,000/1,000행의 최소 조건입니다. 군집 간격은600 raw이며 독립 사건임을 보장하지 않습니다. 선정은 학습·검증 구간만 사용했습니다. 08M01은 검증 음성984개로 사전 기준에16개 못 미쳐 제외했습니다. 경계가 물리적인 충분성 기준이라는 뜻은 아니지만 결과에 맞춰 변경하지 않았습니다. 음성0은 정상 운전 부재가 아니라 현재 보수적 라벨 근거 부족을 뜻합니다.'),
      ('code',"eligibility=table('eligibility')\nexpected=eligibility[list(PROTOCOL['eligibility'])].ge(pd.Series(PROTOCOL['eligibility'])).all(axis=1)\nassert expected.equals(eligibility.eligible)\nassert eligibility[eligibility.selected].Tool.tolist()==selection['selected_tools']\nassert len(selection['selected_tools'])<=3\ndisplay(eligibility)\nfigure('eligibility')\nfigure('coverage')"),
      ('markdown','## 2. CUDA 모델과 실제 입력 재현\n\n03M02 알려진 학습123,796행(양성500/음성123,296)만 전처리와 모델 fit에 사용했습니다. B32, 깊이3, 양성 가중1, seed42로 공통 기준과 같은 설정입니다. validation 조기 종료의 선택 트리는1개입니다. 아래에서는 이미 본 validation128행을 원래 특징으로 다시 읽어 저장 모델/전처리 점수와 대조합니다. 모델이나 전처리를 다시 fit하지 않습니다.'),
      ('code',"import joblib,xgboost as xgb\nfrom src.features import schema\nruns=table('training_summary')\nassert runs.device.eq('cuda:0').all()\nfor tool in selection['selected_tools']:\n    cfg=readjson(OUT/(tool+'_booster_config.json'))\n    assert cfg['learner']['generic_param']['device']=='cuda:0'\n    x,m=load('validation',tool)\n    assert list(x)==schema()['B'] and not {'Tool','time','TTF','audit_label'}&set(x)\n    prep=joblib.load(OUT/(tool+'_preprocessor.joblib'))\n    model=joblib.load(OUT/(tool+'_model.joblib'))\n    score=model.get_booster().predict(xgb.DMatrix(prep.transform(x.iloc[:128]).astype('float32')),iteration_range=(0,model.best_iteration+1))\n    saved=pd.read_parquet(OUT/(tool+'_validation_predictions.parquet'))\n    np.testing.assert_allclose(score,saved.score.iloc[:128],rtol=1e-6,atol=1e-7)\n    print(tool,'validation 실제 입력128행 재현 일치; 후반 재추론 없음')\ndisplay(runs)\nfigure('learning')"),
      ('markdown','## 3. 세 방식과 동결 임계값\n\n공통·기존 임계값 / 공통·장비별 임계값 / 장비 전용을 동일 입력으로 비교합니다. 두 장비별 방식의 숫자 임계값은 validation에서만 선택하고 후반 예측 전에 동결했습니다. 기존 공통 임계값은 전체 장비 기준이므로03M02의 개별 상한을 보장하지 않습니다.'),
      ('code',"from datetime import datetime\nassert datetime.fromisoformat(frozen['frozen_at_utc'])<datetime.fromisoformat(access['opened_at_utc'])\nassert digest(OUT/'frozen_manifest.json')==access['frozen_manifest_sha256']\nfor path,h in frozen['sha256'].items():assert digest(ROOT/path)==h,path\npoints=table('validation_points')\ndisplay(points[['Tool','method','budget','threshold','detected_events','available_events','recorded_events','alarm_episodes_per_10000_raw']])\ndisplay(pd.DataFrame(frozen['points']))\nfigure('comparison')"),
      ('markdown','## 4. 저장된 후반 예측과 경보 부담\n\n기록27개 중 입력 가용3개입니다. 전용 모델은0개 검출/경보228·289개였고, 공통·장비별 임계값도0개 검출/141개 경보였습니다. 기존 공통 높은 설정은2개를 검출했으나 경보5,411개, 부담20.253/10,000 raw로 비교 상한10을 넘었습니다. 이를 동일 부담에서의 우월성으로 주장하지 않습니다.\n\n후반의 알려진 라벨21행이 모두 양성이므로 AP/ROC-AUC는 미산출입니다. 대부분 경보는 미확인 시작이며 확정 오경보가 아닙니다.'),
      ('code',"summary=table('later_summary')\ncommon=pd.read_parquet(ROOT/'outputs/stage6/holdout_predictions.parquet')\nfor tool in selection['selected_tools']:\n    p=pd.read_parquet(OUT/(tool+'_later_predictions.parquet'))\n    assert digest(OUT/(tool+'_later_predictions.parquet'))==access['prediction_sha256'][tool]\n    g=common[common.Tool.eq(tool)].sort_values('time').reset_index(drop=True)\n    pd.testing.assert_frame_equal(p.drop(columns='score'),g.drop(columns='score'))\n    for point in [r for r in frozen['points'] if r['Tool']==tool]:\n        r=summary[summary.Tool.eq(tool)&summary.method.eq(point['method'])&summary.budget.eq(point['budget'])].iloc[0]\n        assert r.threshold==point['threshold']\ndisplay(table('comparison_display'))\ndisplay(table('paired_events'))\ndisplay(table('later_classification'))\nfigure('alarm_burden')"),
      ('markdown','## 5. 실제 고장 구간과 결론\n\n공통 모델만 검출한 첫 고장과 두 모델 모두 놓친 입력 가용 고장을 사후 설명용으로 선정했습니다. 실제 센서와 저장 예측만 표시하며 공백/세그먼트를 연결하지 않습니다. 전용 모델을 만든다는 것만으로 개선되지는 않았습니다.03M02의 입력 누락24개 고장과 다른 장비의 음성 라벨 부족 원인을 먼저 확인하는 것이 다음 우선순위입니다.\n\n이번 전용 모델은 연구 산출물로 보존하고 기존 모델을 대체하지 않습니다. 추후 개선에는 새 검증 자료가 필요합니다. 한 대/가용 고장3개로 일반화 우월성이나 통계적 유의성을 주장하지 않습니다.'),
      ('code',"display(pd.DataFrame([{k:v for k,v in c.items() if k!='query'} for c in readjson(OUT/'case_examples.json')]))\nfigure('event_cases')\nchecks=readjson(OUT/'checks.json')\nassert all(c['passed'] for c in checks['checks'])\nassert checks['additional_later_inference_during_validation']==0\nverify_previous()\nprint('실제 산출물 검사:',len(checks['checks']),'PASS · 기존 최종 결과 보존')\nprint('Notebook 후반 추론0회 · 재학습0회 · 임계값 탐색0회')")
    ]
    book.cells=[nb.v4.new_code_cell(t) if k=='code' else nb.v4.new_markdown_cell(t) for k,t in blocks]
    path=ROOT/'notebooks/16_equipment_specialists.ipynb';nb.write(book,path);start=time.monotonic();NotebookClient(book,timeout=300,kernel_name='phm2018-v3',resources={'metadata':{'path':str(ROOT)}}).execute();nb.write(book,path)
    cells=[c for c in book.cells if c.cell_type=='code'];errors=[o for c in cells for o in c.outputs if o.output_type=='error'];result=dict(notebook='16_equipment_specialists',code_cells=len(cells),executed=sum(c.execution_count is not None for c in cells),errors=len(errors),elapsed_seconds=time.monotonic()-start,additional_later_inference=0,validation_roundtrip_rows_per_tool=128)
    dump_json(OUT/'notebook_execution.json',result);print(result)


if __name__=='__main__':main()
